using System; public class Solution { public int MaxProfit(int k, int[] p) { int n = p.Length; if (n == 0 || k == 0) return 0; if (k >= n / 2) { int ans = 0; for (int i = 1; i < n; i++) ans += Math.Max(p[i] - p[i - 1], 0); return ans; } int[] buy = new int[k + 1], sell = new int[k + 1]; Array.Fill(buy, int.MaxValue); foreach (int price in p) for (int t = 1; t <= k; t++) { buy[t] = Math.Min(buy[t], price - sell[t - 1]); sell[t] = Math.Max(sell[t], price - buy[t]); } return sell[k]; } }
